ServerEvents.generateData('last', function (event) {
  var ok = 0
  for (var i = 0; i < PC_TABLES.length; i++) {
    try {
      event.text(PC_TABLES[i][0], PC_TABLES[i][1])
      ok++
    } catch (e) {
      console.error('[parchemins_coffres] ' + PC_TABLES[i][0] + ' : ' + e)
    }
  }
  console.info('[parchemins_coffres] ' + ok + '/' + PC_TABLES.length + ' tables de coffres remplacées')
})
